package t.mma.hooks.items.homeextension

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

internal object HomeMusicArtwork {
 private val cache=mutableMapOf<String,Bitmap>()
 @Synchronized fun load(c:Context,style:Int,name:String):Bitmap? {
  val key="$style/$name";cache[key]?.let{return it}
  val path="music_style$style/$name.webp"
  val bitmap=runCatching{c.createPackageContext("t.mma",Context.CONTEXT_IGNORE_SECURITY).assets.open(path).use{BitmapFactory.decodeStream(it)}}.getOrNull()
   ?:runCatching{HomeMusicArtwork::class.java.classLoader?.getResourceAsStream("assets/$path")?.use{BitmapFactory.decodeStream(it)}}.getOrNull()
   ?:runCatching{val bytes=Base64.decode(encoded(style,name),Base64.DEFAULT);BitmapFactory.decodeByteArray(bytes,0,bytes.size)}.getOrNull()
  if(bitmap!=null)cache[key]=bitmap else android.util.Log.e("Hchat-HomeMusic","Music artwork decode failed: $key")
  return bitmap
 }
 private fun encoded(style:Int,name:String):String=when("$style/$name"){
 "2/card" -> image2card().joinToString("")
 "2/player" -> image2player().joinToString("")
 "2/avatar" -> image2avatar().joinToString("")
 "3/card" -> image3card().joinToString("")
 "3/player" -> image3player().joinToString("")
 "3/avatar" -> image3avatar().joinToString("")
 else -> error("Unknown music artwork")
 }
